import { test, expect } from '@playwright/test';

test.describe('AI Chat Assistant E2E', () => {
  test('User can submit message, receive streaming response, and stop generation', async ({ page }) => {
    await page.goto('/chat');

    const promptInput = page.getByPlaceholder(/ask a question/i);
    const submitButton = page.getByRole('button', { name: /send/i });

    // 1. Submit prompt
    await promptInput.fill('Summarize the quarterly cloud architecture report');
    await submitButton.click();

    // 2. Assert stop button appears during active streaming
    const stopButton = page.getByRole('button', { name: /stop/i });
    await expect(stopButton).toBeVisible();

    // 3. Assert streaming content container begins populating
    const assistantMessage = page.locator('.assistant-message').last();
    await expect(assistantMessage).toContainText(/quarterly/i, { timeout: 5000 });

    // 4. Click stop to abort generation
    await stopButton.click();
    await expect(stopButton).toBeHidden();
    await expect(promptInput).toBeEnabled();
  });

  test('Interactive tool approval modal requires user confirmation', async ({ page }) => {
    await page.goto('/chat');
    await page.getByPlaceholder(/ask a question/i).fill('Delete obsolete test database cluster');
    await page.getByRole('button', { name: /send/i }).click();

    // Verify human approval modal pops up
    const approvalModal = page.locator('.approval-modal');
    await expect(approvalModal).toBeVisible();
    await expect(approvalModal).toContainText('requires approval');

    // Approve action
    await page.getByRole('button', { name: /approve/i }).click();
    await expect(approvalModal).toBeHidden();
    await expect(page.locator('.tool-status-completed')).toBeVisible();
  });
});
